mapper.select:
SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY price_10k_won / area_sqm) AS medianPricePerSqm,
       COUNT(*) AS comparableCount
FROM trade
WHERE cancel_date IS NULL
  AND share_type IS NULL
  AND property_type = #{propertyType}
  AND sgg_nm = #{sggNm}
  AND bjdong_nm = #{bjdongNm}
  AND area_sqm BETWEEN #{areaMin} AND #{areaMax}
  AND build_year >= #{buildYearMin}
  AND build_year <= #{buildYearMax}
  AND contract_date >= #{recencyCutoff}

